SELECT username, maxOrNull(datetime) as Last_Access FROM ${table} 
WHERE $__timeFilter(datetime) 
AND ${generalescaping}
AND $__adHocFilter() 

AND username != '-'

group by username 
order by Last_Access desc
LIMIT ${querieslimit}
SETTINGS hdx_query_max_execution_time=60, hdx_query_admin_comment='db=${__dashboard}; dp=Last ${querieslimit} active users; du=${__user.login}'

