SELECT clientVersion, count(distinct clientId)
FROM ${table} 
WHERE clientVersion IS NOT NULL and clientVersion != '-' 
and username != '-'
AND $__timeFilter(datetime) 
AND ${generalescaping}
AND $__adHocFilter() 
group by clientVersion
limit ${querieslimit}
SETTINGS hdx_query_max_execution_time=60, hdx_query_admin_comment='db=${__dashboard}; dp=Number of client version; du=${__user.login}'

SELECT clientVersion, clientId, deviceType, username, maxOrNull(datetime) as Last_Access FROM ${table}
WHERE clientVersion IS NOT NULL and clientVersion != '-'
and username != '-'
AND $__timeFilter(datetime) 
AND ${generalescaping}
AND $__adHocFilter() 
GROUP BY clientVersion, clientId, deviceType, username
order by Last_Access desc
limit ${querieslimit}
